
public class A1Q15 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String s = "Java";
		System.out.println(s + 2 + 3);
		System.out.println(2 + 3 + s);
		System.out.println(s + (2 + 3));
		System.out.println("Programming " + s + " " + 2 + 3);
		System.out.println("Programming " + (2 + 3) + " " + s);
		
		// Similar concept as Q6
	}

}
